import React from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import { MAX_LENGTHS_API } from '@proton/shared/lib/calendar/constants';

import useGetCalendarSetup from '../hooks/useGetCalendarSetup';
import SubscribeCalendarModal from './SubscribeCalendarModal';

jest.mock('../hooks/useGetCalendarSetup', () => ({
    __esModule: true,
    default: jest.fn(() => ({ error: false, loading: false })),
}));
jest.mock('../hooks/useGetCalendarActions', () => ({
    __esModule: true,
    default: () => ({ handleCreateCalendar: jest.fn() }),
}));
jest.mock('../calendarModal/calendarModalState', () => ({
    getDefaultModel: () => ({}),
    getCalendarPayload: jest.fn(),
    getCalendarSettingsPayload: jest.fn(),
}));
jest.mock('../../../hooks', () => ({ useLoading: () => [false, (promise: Promise<unknown>) => promise] }));
jest.mock('../../error', () => ({ GenericError: () => <div>Setup error</div> }));
jest.mock('../../../components', () => ({
    BasicModal: ({ children, footer, onSubmit }: any) => (
        <form
            onSubmit={(event) => {
                event.preventDefault();
                onSubmit();
            }}
        >
            {children}
            {footer}
        </form>
    ),
    Form: 'form',
    Button: ({ children, ...props }: any) => <button {...props}>{children}</button>,
    Href: ({ children, ...props }: any) => <a {...props}>{children}</a>,
    InputFieldTwo: ({ value, onChange, warning, error, ...props }: any) => (
        <>
            <input value={value} onChange={onChange} data-test-id={props['data-test-id']} />
            {warning && <div role="status">{warning}</div>}
            {error && <div role="alert">{error}</div>}
        </>
    ),
    Loader: () => <div>Loading</div>,
}));

const setupHook = useGetCalendarSetup as jest.Mock;

const enterURL = (value: string) => {
    fireEvent.change(screen.getByTestId('input:calendar-subscription'), { target: { value } });
};

const getSubmit = () => screen.getByRole('button', { name: 'Add calendar' });

describe('SubscribeCalendarModal URL validation', () => {
    beforeEach(() => {
        setupHook.mockReturnValue({ error: false, loading: false });
    });

    it('trims input and enables submission only for valid URLs within the limit', () => {
        render(<SubscribeCalendarModal isOpen />);
        expect(getSubmit()).toBeDisabled();

        enterURL('  https://example.com/calendar.ics  ');
        expect(screen.getByTestId('input:calendar-subscription')).toHaveValue('https://example.com/calendar.ics');
        expect(getSubmit()).toBeEnabled();

        enterURL('not a URL');
        expect(getSubmit()).toBeDisabled();

        enterURL(`https://example.com/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL - 'https://example.com/'.length)}`);
        expect(getSubmit()).toBeEnabled();

        enterURL(`https://example.com/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL - 'https://example.com/'.length + 1)}`);
        expect(getSubmit()).toBeDisabled();
        expect(screen.getByRole('status')).toHaveTextContent('URL is too long');
    });

    it('shows one warning in extension, public link, then length priority', () => {
        render(<SubscribeCalendarModal isOpen />);

        enterURL(`https://calendar.google.com/public/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}`);
        expect(screen.getByRole('status')).toHaveTextContent('This link might be wrong');
        expect(screen.queryByText('URL is too long')).not.toBeInTheDocument();

        enterURL(`https://calendar.google.com/public/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}.ics`);
        expect(screen.getByRole('status')).toHaveTextContent(
            'By using this link, Google will make the calendar you are subscribing to public'
        );

        enterURL('https://outlook.live.com/calendar');
        expect(screen.getByRole('status')).toHaveTextContent('This link might be wrong');

        enterURL('https://example.com/calendar.ics');
        expect(screen.queryByRole('status')).not.toBeInTheDocument();
    });

    it('uses the same disabled state in the setup error flow', () => {
        setupHook.mockReturnValue({ error: true, loading: false });
        render(<SubscribeCalendarModal isOpen />);
        expect(screen.getByRole('button', { name: 'Close' })).toBeDisabled();
    });
});

